# Let's analyze the differences between inputs and outputs
inputs = ['cza', 'axja', 'ibdcdd', 'jxx', 'vd']
outputs = ['cza', 'axja', 'ixchdhd', 'jxx', 'vhd']

print("Input -> Output differences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")

# Let's look at character-by-character differences
print("\nCharacter-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{inp} vs {outp}:")
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(outp):
            print(f"  Position {j}: '{outp[j]}' (added)")

